def f(nums):
    for x in nums:
        t = 0
        t = t + x
    return t

def g(nums):
    t = 0
    for x in nums:
        t = t + x
        return t

print(f([4, 5, 6]), g([4, 5, 6]))

def count_a(s):
    for ch in s:
        n = 0
        if ch == 'a':
            n += 1
    return n

def has_a(s):
    for ch in s:
        if ch == 'a':
            return True
        return False

print(count_a('banana'), has_a('banana'))

def biggest(nums):
    for x in nums:
        best = nums[0]
        if x > best:
            best = x
    return best

def first_even(nums):
    for x in nums:
        if x % 2 == 0:
            return x
        return None

print(biggest([3, 9, 2]), first_even([3, 4]))
